1	package api
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"io"
8		"net/http"
9		"net/url"
10		"strconv"
11		"strings"
12	
13		"github.com/gin-gonic/gin"
14	
15		"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
17	)
18	
19	// Error codes published by the placements API.
20	const (
21		codeInvalidInput = "InvalidPlacementInputError"
22		codeNotFound     = "PlacementNotFoundError"
23		codeConflict     = "PlacementConflictError"
24		codeStorageDown  = "storage_unavailable"
25	)
26	
27	var errInvalidPlacement = errors.New("invalid placement input")
28	
29	type placementHandler struct {
30		svc *service.Service
31		st  *store.Store
32	}
33	
34	func writeAPIError(c *gin.Context, status int, code, message string) {
35		c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
36	}
37	
38	// createPlacement handles POST /v1/placements. The transport layer only
39	// parses and validates the request and maps the business acceptance outcome
40	// to its HTTP status; scheduling and idempotency/conflict decisions belong to
41	// service.Accept.
42	func (h *placementHandler) createPlacement(c *gin.Context) {
43		body, err := io.ReadAll(c.Request.Body)
44		if err != nil {
45			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
46			return
47		}
48		p, err := parsePlacement(body)
49		if err != nil {
50			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
51			return
52		}
53	
54		stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
55		if err != nil {
56			writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
57			return
58		}
59		switch outcome {
60		case service.Created:
61			c.JSON(http.StatusCreated, stored)
62		case service.Identical:
63			c.JSON(http.StatusOK, stored)
64		case service.Conflict:
65			writeAPIError(c, http.StatusConflict, codeConflict,
66				"a placement with this namespace and name already exists with different content")
67		}
68	}
69	
70	// listPlacements handles GET /v1/placements, both the single-record form
71	// (namespace+name) and the filtered-list form.
72	func (h *placementHandler) listPlacements(c *gin.Context) {
73		params, err := parseQuery(c.Request.URL.RawQuery)
74		if err != nil {
75			writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
76			return
77		}
78	
79		if name, hasName := params["name"]; hasName {
80			namespace, hasNamespace := params["namespace"]
81			_, hasQueue := params["queue"]
82			_, hasNode := params["node"]
83			if !hasNamespace || hasQueue || hasNode {
84				writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
85				return
86			}
87			rec, err := h.st.Get(c.Request.Context(), namespace, name)
88			if errors.Is(err, store.ErrNotFound) {
89				writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
90				return
91			}
92			if err != nil {
93				writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
94				return
95			}
96			c.JSON(http.StatusOK, rec)
97			return
98		}
99	
100		recs, err := h.st.List(c.Request.Context(), store.ListFilter{
101			Namespace: params["namespace"],
102			Queue:     params["queue"],
103			Node:      params["node"],
104		})
105		if err != nil {
106			writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
107			return
108		}
109		if recs == nil {
110			recs = []*store.Placement{}
111		}
112		c.JSON(http.StatusOK, gin.H{"items": recs})
113	}
114	
115	var allowedQueryParams = map[string]bool{
116		"namespace": true,
117		"name":      true,
118		"queue":     true,
119		"node":      true,
120	}
121	
122	// parseQuery accepts only the four documented parameters. Empty values,
123	// repeated parameters and malformed query strings are rejected.
124	func parseQuery(raw string) (map[string]string, error) {
125		values, err := url.ParseQuery(raw)
126		if err != nil {
127			return nil, errInvalidPlacement
128		}
129		params := make(map[string]string, len(values))
130		for key, vals := range values {
131			if !allowedQueryParams[key] || len(vals) != 1 || vals[0] == "" {
132				return nil, errInvalidPlacement
133			}
134			params[key] = vals[0]
135		}
136		return params, nil
137	}
138	
139	// ---------------------------------------------------------------------------
140	// Strict request parsing.
141	//
142	// The token walk below enforces, before anything is stored:
143	//   - the body is one JSON object with exactly the documented members,
144	//   - no unknown or duplicate member names at any level,
145	//   - no trailing data after the root object,
146	//   - every value has the declared JSON type and range (null is never accepted
147	//     where a value is required; omitted selector/labels default to {}),
148	//   - node names are unique.
149	// ---------------------------------------------------------------------------
150	
151	var topLevelFields = map[string]bool{
152		"namespace": true,
153		"name":      true,
154		"queue":     true,
155		"priority":  true,
156		"resources": true,
157		"selector":  true,
158		"nodes":     true,
159	}
160	
161	var resourceFields = map[string]bool{"cpu": true, "memory": true}
162	
163	var nodeFields = map[string]bool{
164		"name":   true,
165		"cpu":    true,
166		"memory": true,
167		"labels": true,
168	}
169	
170	func parsePlacement(body []byte) (*store.Placement, error) {
171		dec := json.NewDecoder(bytes.NewReader(body))
172		dec.UseNumber()
173	
174		tok, err := dec.Token()
175		if err != nil {
176			return nil, errInvalidPlacement
177		}
178		if d, ok := tok.(json.Delim); !ok || d != '{' {
179			return nil, errInvalidPlacement
180		}
181	
182		p := &store.Placement{}
183		seen := map[string]bool{}
184		for dec.More() {
185			keyTok, err := dec.Token()
186			if err != nil {
187				return nil, errInvalidPlacement
188			}
189			key, ok := keyTok.(string)
190			if !ok || !topLevelFields[key] || seen[key] {
191				return nil, errInvalidPlacement
192			}
193			seen[key] = true
194	
195			var raw json.RawMessage
196			if err := dec.Decode(&raw); err != nil {
197				return nil, errInvalidPlacement
198			}
199	
200			switch key {
201			case "namespace", "name", "queue":
202				s, err := parseTrimmedString(raw)
203				if err != nil {
204					return nil, err
205				}
206				switch key {
207				case "namespace":
208					p.Namespace = s
209				case "name":
210					p.Name = s
211				case "queue":
212					p.Queue = s
213				}
214			case "priority":
215				n, err := parseBoundedInt(raw, 32)
216				if err != nil {
217					return nil, err
218				}
219				p.Priority = int32(n)
220			case "resources":
221				r, err := parseResources(raw)
222				if err != nil {
223					return nil, err
224				}
225				p.Resources = r
226			case "selector":
227				m, err := parseStringMap(raw)
228				if err != nil {
229					return nil, err
230				}
231				p.Selector = m
232			case "nodes":
233				nodes, err := parseNodes(raw)
234				if err != nil {
235					return nil, err
236				}
237				p.Nodes = nodes
238			}
239		}
240		if _, err := dec.Token(); err != nil {
241			return nil, errInvalidPlacement // closing '}'
242		}
243		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
244			return nil, errInvalidPlacement // trailing data
245		}
246	
247		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
248			if !seen[required] {
249				return nil, errInvalidPlacement
250			}
251		}
252		if p.Selector == nil {
253			p.Selector = map[string]string{}
254		}
255		return p, nil
256	}
257	
258	func parseResources(raw json.RawMessage) (store.Resources, error) {
259		var r store.Resources
260		obj, err := parseStrictObject(raw, resourceFields)
261		if err != nil {
262			return r, err
263		}
264		cpuRaw, ok := obj["cpu"]
265		if !ok {
266			return r, errInvalidPlacement
267		}
268		memoryRaw, ok := obj["memory"]
269		if !ok {
270			return r, errInvalidPlacement
271		}
272		cpu, err := parseBoundedInt(cpuRaw, 64)
273		if err != nil || cpu <= 0 {
274			return r, errInvalidPlacement
275		}
276		memory, err := parseBoundedInt(memoryRaw, 64)
277		if err != nil || memory <= 0 {
278			return r, errInvalidPlacement
279		}
280		return store.Resources{CPU: cpu, Memory: memory}, nil
281	}
282	
283	func parseNodes(raw json.RawMessage) ([]store.Node, error) {
284		if isNull(raw) {
285			return nil, errInvalidPlacement
286		}
287		dec := json.NewDecoder(bytes.NewReader(raw))
288		tok, err := dec.Token()
289		if err != nil {
290			return nil, errInvalidPlacement
291		}
292		if d, ok := tok.(json.Delim); !ok || d != '[' {
293			return nil, errInvalidPlacement
294		}
295	
296		nodes := []store.Node{}
297		names := map[string]bool{}
298		for dec.More() {
299			var elem json.RawMessage
300			if err := dec.Decode(&elem); err != nil {
301				return nil, errInvalidPlacement
302			}
303			obj, err := parseStrictObject(elem, nodeFields)
304			if err != nil {
305				return nil, err
306			}
307			nameRaw, ok := obj["name"]
308			if !ok {
309				return nil, errInvalidPlacement
310			}
311			cpuRaw, ok := obj["cpu"]
312			if !ok {
313				return nil, errInvalidPlacement
314			}
315			memoryRaw, ok := obj["memory"]
316			if !ok {
317				return nil, errInvalidPlacement
318			}
319			name, err := parseTrimmedString(nameRaw)
320			if err != nil {
321				return nil, err
322			}
323			cpu, err := parseBoundedInt(cpuRaw, 64)
324			if err != nil || cpu < 0 {
325				return nil, errInvalidPlacement
326			}
327			memory, err := parseBoundedInt(memoryRaw, 64)
328			if err != nil || memory < 0 {
329				return nil, errInvalidPlacement
330			}
331			labels := map[string]string{}
332			if labelRaw, ok := obj["labels"]; ok {
333				labels, err = parseStringMap(labelRaw)
334				if err != nil {
335					return nil, err
336				}
337			}
338			if names[name] {
339				return nil, errInvalidPlacement
340			}
341			names[name] = true
342			nodes = append(nodes, store.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
343		}
344		if _, err := dec.Token(); err != nil {
345			return nil, errInvalidPlacement // closing ']'
346		}
347		return nodes, nil
348	}
349	
350	// parseStrictObject decodes an object whose member names are restricted to
351	// allowed. Both unknown and duplicate names are rejected.
352	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
353		if isNull(raw) {
354			return nil, errInvalidPlacement
355		}
356		dec := json.NewDecoder(bytes.NewReader(raw))
357		tok, err := dec.Token()
358		if err != nil {
359			return nil, errInvalidPlacement
360		}
361		if d, ok := tok.(json.Delim); !ok || d != '{' {
362			return nil, errInvalidPlacement
363		}
364		return readObjectMembers(dec, allowed)
365	}
366	
367	// parseStringMap decodes an object with arbitrary string keys and string
368	// values; null or non-string values are rejected.
369	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
370		if isNull(raw) {
371			return nil, errInvalidPlacement
372		}
373		dec := json.NewDecoder(bytes.NewReader(raw))
374		tok, err := dec.Token()
375		if err != nil {
376			return nil, errInvalidPlacement
377		}
378		if d, ok := tok.(json.Delim); !ok || d != '{' {
379			return nil, errInvalidPlacement
380		}
381	
382		out := map[string]string{}
383		raws, err := readObjectMembers(dec, nil)
384		if err != nil {
385			return nil, err
386		}
387		for key, value := range raws {
388			s, err := parseJSONString(value)
389			if err != nil {
390				return nil, err
391			}
392			out[key] = s
393		}
394		return out, nil
395	}
396	
397	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
398		out := map[string]json.RawMessage{}
399		for dec.More() {
400			keyTok, err := dec.Token()
401			if err != nil {
402				return nil, errInvalidPlacement
403			}
404			key, ok := keyTok.(string)
405			if !ok {
406				return nil, errInvalidPlacement
407			}
408			if allowed != nil && !allowed[key] {
409				return nil, errInvalidPlacement
410			}
411			if _, dup := out[key]; dup {
412				return nil, errInvalidPlacement
413			}
414			var value json.RawMessage
415			if err := dec.Decode(&value); err != nil {
416				return nil, errInvalidPlacement
417			}
418			out[key] = value
419		}
420		if _, err := dec.Token(); err != nil {
421			return nil, errInvalidPlacement // closing '}'
422		}
423		return out, nil
424	}
425	
426	// parseTrimmedString accepts a JSON string that is non-empty and has no
427	// leading or trailing Unicode whitespace.
428	func parseTrimmedString(raw json.RawMessage) (string, error) {
429		s, err := parseJSONString(raw)
430		if err != nil {
431			return "", err
432		}
433		if s == "" || s != strings.TrimSpace(s) {
434			return "", errInvalidPlacement
435		}
436		return s, nil
437	}
438	
439	func parseJSONString(raw json.RawMessage) (string, error) {
440		if isNull(raw) {
441			return "", errInvalidPlacement
442		}
443		var s string
444		if err := json.Unmarshal(raw, &s); err != nil {
445			return "", errInvalidPlacement
446		}
447		return s, nil
448	}
449	
450	// parseBoundedInt accepts an integral JSON number without fraction or exponent
451	// that fits a signed integer of the given bit size (32 or 64).
452	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
453		if isNull(raw) {
454			return 0, errInvalidPlacement
455		}
456		dec := json.NewDecoder(bytes.NewReader(raw))
457		dec.UseNumber()
458		var value any
459		if err := dec.Decode(&value); err != nil {
460			return 0, errInvalidPlacement
461		}
462		number, ok := value.(json.Number)
463		if !ok {
464			return 0, errInvalidPlacement
465		}
