299		}
300		// UTF-8 byte order: 'a'(0x61) < 'z'(0x7A) < 'ä'(0xC3..) < '日'(0xE6..).
301		submit("z", "n2", "q1", "host-1")
302		submit("a", "n2", "q1", "host-1")
303		submit("ä", "n1", "q2", "host-2")
304		submit("日", "n1", "q1", "host-1")
305		submit("a", "n1", "q2", "host-2")
306	
307		all := doRequest(t, h, http.MethodGet, "/v1/placements", "")
308		var order []string
309		for _, item := range decodeBody(t, all)["items"].([]any) {
310			m := item.(map[string]any)
311			order = append(order, m["namespace"].(string)+"/"+m["name"].(string))
312		}
313		want := []string{"a/n1", "a/n2", "z/n2", "ä/n1", "日/n1"}
314		if fmt.Sprint(order) != fmt.Sprint(want) {
315			t.Fatalf("order = %v, want %v", order, want)
316		}
