323		if len(decodeBody(t, byNode)["items"].([]any)) != 2 {
324			t.Fatalf("node+queue intersection: %s", byNode.Body.String())
325		}
326		byNamespace := doRequest(t, h, http.MethodGet, "/v1/placements?namespace=a", "")
327		if len(decodeBody(t, byNamespace)["items"].([]any)) != 2 {
328			t.Fatalf("namespace filter: %s", byNamespace.Body.String())
329		}
330		empty := doRequest(t, h, http.MethodGet, "/v1/placements?queue=nope", "")
